    ctx.beginPath(); ctx.arc(CX, CY, ARENA_R, 0, 7);
    ctx.fillStyle = 'rgba(20,32,68,.55)'; ctx.fill();
    ctx.lineWidth = 3; ctx.strokeStyle = '#3f5da8'; ctx.stroke();
    for (const r of [90,160,220]) {
      ctx.beginPath(); ctx.arc(CX, CY, r, 0, 7);
      ctx.strokeStyle = 'rgba(90,120,200,.25)'; ctx.lineWidth = 1.5;
      ctx.setLineDash([6,6]); ctx.stroke(); ctx.setLineDash([]);
    }
    // planet core
    const g = ctx.createRadialGradient(CX,CY,2,CX,CY,44);
    g.addColorStop(0,'#9ff5e0'); g.addColorStop(.4,'#2fbf9a'); g.addColorStop(1,'rgba(20,60,50,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(CX,CY,44,0,7); ctx.fill();
    ctx.fillStyle = '#0e2a23'; ctx.beginPath(); ctx.arc(CX,CY,16,0,7); ctx.fill();
    ctx.strokeStyle = '#57f2c6'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(CX,CY,16,0,7); ctx.stroke();

    // scraps (yellow diamonds)
    for (const s of scraps) {
      ctx.save(); ctx.translate(s.x, s.y); ctx.rotate(s.spin);
      ctx.fillStyle = '#ffd54a'; ctx.strokeStyle = '#7a5b00'; ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0,-9); ctx.lineTo(7,0); ctx.lineTo(0,9); ctx.lineTo(-7,0); ctx.closePath();
      ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#fff3b0';
      ctx.beginPath(); ctx.moveTo(0,-4); ctx.lineTo(3,0); ctx.lineTo(0,4); ctx.lineTo(-3,0); ctx.closePath(); ctx.fill();
      ctx.restore();
    }

    // hazards (red jagged rocks)
    for (const hz of hazards) {
      ctx.save(); ctx.translate(hz.x, hz.y); ctx.rotate(hz.spin);
      ctx.fillStyle = '#3a0f18'; ctx.strokeStyle = '#ff4d5e'; ctx.lineWidth = 2.5;
      ctx.beginPath();
      const n = 8;
      for (let i = 0; i <= n; i++) {
        const a = (i/n)*Math.PI*2;
        const rr = hz.size * (i%2 ? 0.78 : 1.08);
        const px = Math.cos(a)*rr, py = Math.sin(a)*rr;
        i ? ctx.lineTo(px,py) : ctx.moveTo(px,py);
      }
      ctx.closePath(); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#ff8a94';
      ctx.beginPath(); ctx.arc(0,0,hz.size*0.28,0,7); ctx.fill();
      ctx.restore();
    }

    // player drone (triangle)
    if (state !== 'dead' && player) {
      const blink = invuln > 0 && Math.floor(t/100)%2 === 0;
      ctx.save(); ctx.translate(player.x, player.y); ctx.rotate(player.angle + Math.PI/2);
      if (player.thrust) {
        ctx.fillStyle = '#ff9d2e';
        ctx.beginPath(); ctx.moveTo(-5,10); ctx.lineTo(0,10+10+Math.random()*8); ctx.lineTo(5,10); ctx.closePath(); ctx.fill();
      }
      ctx.globalAlpha = blink ? 0.35 : 1;
      ctx.fillStyle = '#57c8f2'; ctx.strokeStyle = '#e8fbff'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(0,-13); ctx.lineTo(9,9); ctx.lineTo(0,4); ctx.lineTo(-9,9); ctx.closePath();
      ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#0a2432'; ctx.beginPath(); ctx.arc(0,-2,3.4,0,7); ctx.fill();
      ctx.restore();
      ctx.globalAlpha = 1;
    }
    ctx.restore();

    if (state === 'play') {
      ctx.fillStyle = 'rgba(160,180,230,.8)';
      ctx.font = '13px system-ui';
      ctx.fillText('Collect +10  •  Hull -34 per hit  •  3 hits = destroyed', 14, H - 12);
    }
  }

  function frame(ts) {
    requestAnimationFrame(frame);
    if (lastTime == null) lastTime = ts;
    let dt = (ts - lastTime) / 1000;
    lastTime = ts;
    dt = Math.min(dt, 0.033);
    if (state === 'play') step(dt);
    draw(ts || 0);
  }

  restartBtn.addEventListener('click', startGame);
  // idle demo behind menu
  startGame(); state = 'menu';
  ovTitle.textContent = 'Orbit Salvage';
  ovText.innerHTML = 'Steer with <kbd>WASD</kbd> or <kbd>&larr;&uarr;&darr;&rarr;</kbd>. Collect yellow scrap (+10). Avoid red debris &mdash; 3 hits destroy the drone.';
  restartBtn.textContent = 'Launch (Enter)';
  overlay.classList.remove('hidden');
  updateHUD();
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>

