const { chromium } = require('/tmp/opencode/pwtest/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 800, height: 700 } });
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  await page.goto('file:///home/runner/work/PlayGround/PlayGround/index.html');
  await page.waitForTimeout(800);
  const hasCanvas = await page.$('#game') !== null;
  const title = await page.title();
  console.log('title:', title, 'hasCanvas:', hasCanvas);
  // launch game
  await page.click('#restartBtn');
  await page.waitForTimeout(500);
  let st = await page.evaluate(() => window.__orbit.state);
  console.log('state after launch:', st);
  const p0 = await page.evaluate(() => ({ x: window.__orbit.player.x, y: window.__orbit.player.y }));
  // steer right + up for 1s
  await page.keyboard.down('d');
  await page.keyboard.down('w');
  await page.waitForTimeout(1000);
  await page.keyboard.up('d');
  await page.keyboard.up('w');
  const p1 = await page.evaluate(() => ({ x: window.__orbit.player.x, y: window.__orbit.player.y }));
  console.log('moved from', JSON.stringify(p0), 'to', JSON.stringify(p1), 'dist=', Math.hypot(p1.x - p0.x, p1.y - p0.y).toFixed(1));
  const moved = Math.hypot(p1.x - p0.x, p1.y - p0.y) > 20;
  console.log('movement OK:', moved);
  // check 3 hazards
  const hz = await page.evaluate(() => window.__orbit.hazards.length);
  console.log('hazards:', hz);
  // check scrap collection by teleporting a scrap onto player
  const s0 = await page.evaluate(() => {
    const o = window.__orbit;
    o.scraps[0].x = o.player.x; o.scraps[0].y = o.player.y;
    return o.score;
  });
  await page.waitForTimeout(300);
  const s1 = await page.evaluate(() => window.__orbit.score);
  console.log('score before/after scrap teleport:', s0, s1, 'collect OK:', s1 >= s0 + 10);
  // damage x3 -> dead + overlay
  await page.evaluate(() => { window.__orbit.hurt(34); });
  await page.waitForTimeout(200);
  await page.evaluate(() => { window.__orbit.hurt(34); });
  await page.waitForTimeout(200);
  await page.evaluate(() => { window.__orbit.hurt(34); });
  await page.waitForTimeout(400);
  const dead = await page.evaluate(() => ({ state: window.__orbit.state, hull: window.__orbit.player.hull }));
  const overlayVisible = await page.evaluate(() => !document.getElementById('overlay').classList.contains('hidden'));
  const ovTitle = await page.textContent('#ovTitle');
  console.log('after 3 hits:', JSON.stringify(dead), 'overlay:', overlayVisible, 'title:', ovTitle);
  // restart via R
  await page.keyboard.press('r');
  await page.waitForTimeout(400);
  const re = await page.evaluate(() => ({ state: window.__orbit.state, score: window.__orbit.score, hull: window.__orbit.player.hull }));
  console.log('after restart:', JSON.stringify(re));
  await page.screenshot({ path: '/tmp/opencode/shot2.png' });
  console.log('console errors:', errors.length ? errors : 'none');
  const pass = moved && hz === 3 && (s1 >= s0 + 10) && dead.state === 'dead' && overlayVisible && re.state === 'play' && re.score === 0 && re.hull === 100 && errors.length === 0;
  console.log(pass ? 'VERIFY PASS' : 'VERIFY FAIL');
  await browser.close();
  process.exit(pass ? 0 : 1);
})().catch(e => { console.error('FATAL', e); process.exit(1); });

